
ALTER TABLE public.articles
  ADD COLUMN external_url TEXT,
  ADD COLUMN external_label TEXT,
  ADD COLUMN is_tool BOOLEAN NOT NULL DEFAULT false;

UPDATE public.categories
SET objectives = ARRAY[
  'Acceder a Abogados Nx, Chattigo, Microsip y Gestión de Mora con tus credenciales propias',
  'Registrar transferencias en el Drive de Carga sin errores de formato',
  'Atender por Gmail y WhatsApp siguiendo los tiempos de respuesta acordados',
  'Armar y actualizar las tablas dinámicas de Excel de tu cartera',
  'Resolver los fallos más habituales de cada sistema antes de escalar'
],
summary = 'Los sistemas que usarás cada día, con acceso directo, guía paso a paso, consejos según tu rol y solución de problemas frecuentes.'
WHERE slug = 'herramientas-clave';

INSERT INTO public.articles (category_id, slug, title, summary, body, reading_minutes, is_required, position, external_url, external_label, is_tool)
SELECT c.id, a.slug, a.title, a.summary, a.body, a.reading_minutes, a.is_required, a.position, a.external_url, a.external_label, a.is_tool
FROM (VALUES
('herramientas-clave','abogados-nx','Portal Abogados Naranja X (Abogados Nx)','Validación de identidad y gestión de casos del estudio. Es el punto de partida de casi toda gestión.','## Para qué sirve\nEl Portal Abogados Nx es el sistema de Naranja X donde validamos identidad, consultamos el estado de un caso y registramos las gestiones realizadas sobre la cartera asignada.\n\n## Paso a paso\n1. Abre el portal con el botón de acceso directo.\n2. Ingresa usuario y clave provistos por tu responsable de área. **No se comparten credenciales**: si no tienes usuario, solicítalo antes de tu primer día de gestión.\n3. Completa la validación que solicita la pantalla.\n4. Busca el caso por número de documento o número de legajo.\n5. Revisa estado, historial y gestiones previas antes de contactar al cliente.\n6. Registra la gestión al finalizar: fecha, canal utilizado, resultado y próximo paso comprometido.\n\n## Consejos según tu rol\n- **Cobranzas**: revisa siempre el historial antes de llamar; evita repetir un ofrecimiento ya rechazado.\n- **Legales**: verifica el estado procesal en el portal antes de emitir cualquier comunicación.\n- **Soporte / back office**: si actualizas datos de contacto, deja constancia en la gestión.\n\n## Solución de problemas\n- **La pantalla de validación no carga**: el portal usa una página clásica (.asp); prueba en Chrome, borra caché y desactiva extensiones de bloqueo.\n- **Usuario bloqueado**: tras varios intentos fallidos se bloquea. Solicita desbloqueo a tu responsable, no crees un segundo usuario.\n- **Sesión que se cierra sola**: la sesión expira por inactividad; guarda la gestión antes de dejar la pantalla abierta.\n- **El caso no aparece**: confirma que el documento no tenga puntos ni espacios y que la cartera esté asignada a tu grupo.',5,true,5,'https://abogados.naranjax.com/AbogadoValida3.asp','Abrir Abogados Nx',true),
('herramientas-clave','drive-carga-transferencias','Drive - Carga de Transferencias','La planilla donde se registran y siguen todas las transferencias de pago. Precisión total: es la fuente de verdad.','## Para qué sirve\nEs la planilla compartida de Google donde se registra cada transferencia informada por un cliente y se sigue su acreditación.\n\n## Paso a paso\n1. Abre la planilla con el botón de acceso directo (necesitas tu cuenta corporativa; si pide permiso, solicítalo a tu responsable).\n2. Ubica la pestaña del período en curso. **Nunca escribas sobre períodos cerrados.**\n3. Carga una fila por transferencia, siempre al final: fecha de pago, documento del cliente, número de caso, importe, banco de origen y comprobante.\n4. Pega el enlace o número del comprobante en la columna correspondiente.\n5. Deja el estado en *Pendiente de acreditación* y actualízalo cuando se confirme.\n6. Registra la misma gestión en Abogados Nx para que el caso quede alineado.\n\n## Reglas de formato\n- Importes sin símbolo de moneda ni texto: solo el número.\n- Fechas en el formato de la planilla; no reescribas la columna.\n- Un pago, una fila. Si te equivocas, no borres la fila: márcala como anulada y carga la correcta.\n\n## Consejos según tu rol\n- **Cobranzas**: carga la transferencia el mismo día en que el cliente la informa.\n- **Administración**: concilia diariamente contra el extracto bancario y cierra estados.\n- **Supervisión**: revisa filas sin comprobante antes del cierre semanal.\n\n## Solución de problemas\n- **No puedo editar**: tienes acceso de solo lectura; pide permiso de edición a tu responsable.\n- **Se rompió una fórmula**: no la reescribas, avisa a Administración; hay historial de versiones para restaurar.\n- **Importe que aparece como texto**: revisa que no haya espacios ni comas de más.\n- **Dos personas cargando a la vez**: refresca antes de cargar para no duplicar la fila.',5,true,6,'https://docs.google.com/spreadsheets/d/110dIngWyhSsd-0r8ooLj-05Lu6_8FKhqKaDi7K6bzj8/edit?gid=263522090#gid=263522090','Abrir planilla de transferencias',true),
('herramientas-clave','gmail-whatsapp','Canales de comunicación: Gmail y WhatsApp','Atención, seguimiento y contacto diario con el cliente. Qué se dice por cada canal y en cuánto tiempo.','## Para qué sirven\n**Gmail** es el canal formal: envío de comprobantes, acuerdos, documentación y cualquier cosa que deba quedar registrada.\n\n**WhatsApp** es el canal ágil: recordatorios, coordinación y respuestas rápidas de seguimiento.\n\n## Paso a paso\n1. Usa siempre la cuenta corporativa; nunca tu correo o número personal.\n2. Identifícate en el primer mensaje: nombre, estudio y motivo del contacto.\n3. Envía documentación por Gmail con el número de caso en el asunto.\n4. Usa WhatsApp para confirmar recepción y coordinar próximos pasos.\n5. Cierra el ciclo registrando el contacto en Abogados Nx.\n\n## Tiempos de respuesta\n- WhatsApp: dentro de las 2 horas hábiles.\n- Gmail: dentro del mismo día hábil.\n- Reclamo o cliente molesto: respuesta inmediata y escalado a tu responsable.\n\n## Consejos según tu rol\n- **Cobranzas**: no envíes importes por WhatsApp sin confirmar identidad del titular.\n- **Atención**: usa plantillas aprobadas; ajusta el saludo, nunca las condiciones.\n- **Legales**: toda comunicación con efecto formal va por Gmail, no por WhatsApp.\n\n## Cuidados de datos\nNo compartas datos de terceros ni fotos de documentación en grupos. Verifica el número antes de enviar información sensible.\n\n## Solución de problemas\n- **WhatsApp no sincroniza**: cierra e inicia sesión de nuevo en el dispositivo asignado; no vincules equipos personales.\n- **Correo que rebota**: verifica el dominio del destinatario y reenvía desde el hilo original.\n- **Cliente que dice no haber recibido nada**: reenvía el hilo de Gmail y deja constancia de la fecha de envío.',4,true,7,'https://mail.google.com','Abrir Gmail',true),
('herramientas-clave','chattigo','Chattigo','Gestión omnicanal de las conversaciones con clientes: WhatsApp, web y redes en una sola bandeja.','## Para qué sirve\nChattigo centraliza las conversaciones entrantes de los distintos canales para que ninguna quede sin respuesta y todo quede medido.\n\n## Paso a paso\n1. Ingresa con el botón de acceso directo y tus credenciales.\n2. Ponte en estado **Disponible** al iniciar tu turno; los casos se asignan automáticamente.\n3. Atiende la conversación asignada, verifica identidad y resuelve o deriva.\n4. Etiqueta la conversación con el motivo correcto antes de cerrarla: de ahí salen los reportes.\n5. Cierra la conversación; no la dejes abierta al terminar el turno.\n6. Registra en Abogados Nx cualquier compromiso asumido.\n\n## Consejos según tu rol\n- **Atención**: usa respuestas rápidas para lo repetitivo y escribe a mano lo sensible.\n- **Cobranzas**: nunca negocies importes sin validar al titular.\n- **Supervisión**: revisa conversaciones sin etiqueta y tiempos de primera respuesta al cierre del día.\n\n## Solución de problemas\n- **No recibo conversaciones**: casi siempre el estado quedó en *No disponible* o en pausa.\n- **No carga la bandeja**: refresca, prueba ventana de incógnito y revisa la conexión.\n- **Conversación duplicada del mismo cliente**: atiende la más reciente y cierra la otra como duplicada.\n- **Se cerró tu sesión en medio de un chat**: vuelve a ingresar; la conversación se reasigna, avisa a tu supervisor para que no se pierda.',4,true,8,'https://login.chattigo.com','Abrir Chattigo',true),
('herramientas-clave','microsip','Microsip (softphone)','El teléfono de tu computadora: llamadas salientes y entrantes de gestión.','## Para qué sirve\nMicrosip es el softphone que usamos para llamar y recibir llamadas desde la computadora, con el interno asignado a tu usuario.\n\n## Paso a paso\n1. Solicita a IT la instalación y los datos de tu cuenta SIP (usuario, dominio y clave). No los compartas.\n2. Abre Microsip y verifica que el estado figure como registrado o en línea.\n3. Conecta la vincha antes de llamar y prueba audio con una llamada interna.\n4. Para llamar: marca el número con la característica completa, sin el 0 ni el 15.\n5. Al recibir una llamada, identifícate con nombre y estudio.\n6. Registra el resultado de la llamada en Abogados Nx al terminar.\n\n## Consejos según tu rol\n- **Cobranzas**: agrupa las llamadas en bloques y ten el caso abierto en pantalla antes de marcar.\n- **Atención**: si prometes devolver el llamado, deja el compromiso registrado con horario.\n- **Supervisión**: revisa las llamadas sin resultado registrado.\n\n## Solución de problemas\n- **Aparece como no registrado**: revisa la conexión, luego usuario, dominio y clave; si persiste, abre ticket a IT.\n- **No se escucha o hay eco**: revisa que la vincha sea el dispositivo de entrada y salida seleccionado; evita usar el micrófono del monitor.\n- **Audio en un solo sentido**: casi siempre es la red o el firewall del lugar donde estás trabajando; prueba en otra red y reporta a IT.\n- **Llamadas que se cortan**: verifica que no estés en wifi saturada; se recomienda cable.',4,true,9,NULL,NULL,true),
('herramientas-clave','gestion-de-mora','Sistema GESTIÓN DE MORA','El software interno de registro y seguimiento de cartera y cobranzas. Es donde vive el estado real de cada deudor.','## Para qué sirve\nEs el sistema interno donde se administra la cartera en mora: estado del deudor, gestiones, promesas de pago, acuerdos y seguimiento.\n\n## Paso a paso\n1. Ingresa con el usuario que te asignó tu responsable de área.\n2. Selecciona la cartera asignada a tu grupo.\n3. Abre el caso y revisa tramo de mora, saldo, historial de gestiones y acuerdos vigentes.\n4. Registra cada gestión con motivo, resultado y fecha del próximo contacto.\n5. Si hay promesa de pago, cárgala con fecha e importe: de ahí sale el seguimiento del día siguiente.\n6. Cuando el pago se acredite, deja el caso alineado con la planilla de transferencias.\n\n## Consejos según tu rol\n- **Cobranzas**: trabaja tu agenda de promesas vencidas antes de tomar casos nuevos.\n- **Administración**: valida que cada pago acreditado tenga su gestión asociada.\n- **Supervisión**: revisa casos sin gestión en los últimos 30 días.\n\n## Solución de problemas\n- **No veo mi cartera**: el permiso se asigna por grupo; pide la asignación a tu responsable.\n- **El saldo no coincide con el portal**: puede haber un pago no acreditado aún; verifica en la planilla de transferencias antes de informar al cliente.\n- **Error al guardar una gestión**: no cierres la ventana, copia el texto, vuelve a ingresar y cárgala de nuevo.\n- **El sistema va lento**: suele ser el horario de cierre; evita reprocesar y reporta si supera los 15 minutos.',5,true,10,NULL,NULL,true),
('herramientas-clave','tablas-dinamicas-excel','Tablas dinámicas de Excel operativas','Las planillas y reportes analíticos con los que se mide la gestión de casos.','## Para qué sirven\nSon los reportes en Excel que resumen la cartera y la gestión: casos por tramo, resultados por gestor, promesas cumplidas y recupero del período.\n\n## Paso a paso\n1. Exporta la base desde Gestión de Mora o desde la planilla de transferencias.\n2. Pega los datos en la pestaña *Datos* de la plantilla, sin filas vacías ni títulos intermedios.\n3. Verifica formatos: fechas como fecha, importes como número.\n4. Ve a la pestaña del reporte y usa **Actualizar todo** (Ctrl + Alt + F5).\n5. Revisa que no aparezcan filas "(en blanco)": significan datos sucios en el origen.\n6. Guarda con el nombre del período y comparte el enlace, no el archivo adjunto.\n\n## Consejos según tu rol\n- **Gestores**: usa el reporte para priorizar el tramo con mayor probabilidad de recupero.\n- **Supervisión**: compara semana contra semana, no día contra día; el ruido diario engaña.\n- **Administración**: cuadra el total del reporte contra la planilla de transferencias antes de informar.\n\n## Solución de problemas\n- **La tabla no toma las filas nuevas**: el origen no es una tabla dinámica de rango completo; amplía el rango de datos o convierte el origen en tabla.\n- **Aparecen duplicados**: revisa espacios al final del documento o del número de caso.\n- **Suma de importes en cero**: la columna quedó como texto; conviértela a número y actualiza.\n- **Archivo muy pesado o lento**: elimina columnas que no usas y evita formatos condicionales sobre columnas completas.',5,false,11,NULL,NULL,true),
('procesos-operativos','circuito-diario-herramientas','El circuito diario: cómo se conectan nuestras herramientas','La ruta completa de una gestión, sistema por sistema, para que nada quede sin registrar.','## El circuito de una gestión\n1. **Gestión de Mora**: abres tu agenda del día y priorizas casos y promesas vencidas.\n2. **Abogados Nx**: validas identidad y revisas el estado real del caso antes de contactar.\n3. **Microsip / Chattigo / WhatsApp / Gmail**: contactas al cliente por el canal que corresponda.\n4. **Gmail**: envías la documentación o el acuerdo que quede formalizado.\n5. **Drive - Carga de Transferencias**: si el cliente informa un pago, lo registras el mismo día.\n6. **Gestión de Mora y Abogados Nx**: registras la gestión, el resultado y el próximo paso.\n7. **Tablas dinámicas de Excel**: al cierre, el reporte mide todo lo anterior.\n\n## Regla de oro\nUna gestión que no quedó registrada no existe: no se cobra, no se mide y no se puede defender.\n\n## Cierre del día\nAntes de terminar tu turno: conversaciones de Chattigo cerradas y etiquetadas, llamadas con resultado cargado, transferencias del día en la planilla y promesas de pago agendadas.\n\n## Si algo falla\nRegistra la gestión en el sistema que sí funcione, deja constancia del incidente y avisa a tu responsable. Nunca dejes la gestión sin registro esperando que el sistema vuelva.',5,true,5,NULL,NULL,false)
) AS a(cat_slug, slug, title, summary, body, reading_minutes, is_required, position, external_url, external_label, is_tool)
JOIN public.categories c ON c.slug = a.cat_slug;
